<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Personal Expense Tracker</title>
    <style>
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background-color: #f5f7fa;
            margin: 20px;
            padding: 0;
        }

        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            max-width: 600px;
            margin-bottom: 25px;
        }

        .expenses-container {
            list-style-type: none;
            max-width: 800px;
        }

        .form-group {
            margin-bottom: 15px;
        }

        label {
            display: block;
            margin-bottom: 5px;
            font-weight: bold;
        }

        input, select {
            width: 100%;
            padding: 8px 10px;
            border: 1px solid #ddd;
            border-radius: 4px;
            box-sizing: border-box;
        }

        input[type="number"], input[type="date"] {
            width: 100%;
        }

        .note-input {
            margin-bottom: 15px;
        }

        button {
            background-color: #4CAF50;
            color: white;
            padding: 10px 15px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 16px;
        }

        button:hover {
            background-color: #45a049;
        }

        .error {
            color: red;
            margin-top: 5px;
            display: none;
        }

        .form-error {
            position: absolute;
            top: -20px;
            left: 0;
            right: 0;
            padding: 15px;
            background-color: #ffebee;
            color: #c62828;
            display: none;
            border-radius: 4px;
        }

        .expense-row {
            border-bottom: 1px solid #eee;
            padding: 10px 0;
            max-width: 250px;
            margin-bottom: 15px;
        }

        .date-picker {
            position: relative;
        }

        .date-input {
            width: 50%;
            height: 25px;
            border: none;
            background-color: #f5f5f5;
            cursor: pointer;
            padding: 0 10px;
            display: flex;
            align-items: center;
            font-size: 14px;
        }

        .date-input:hover {
            background-color: #e9e9e9;
        }

        .delete-btn {
            color: #f44336;
            text-decoration: none;
            cursor: pointer;
        }

        .cat-total {
            font-weight: bold;
            color: #2196F3;
            margin-top: 10px;
            background-color: #e8f5e9;
            padding: 8px;
            border-radius: 4px;
        }

        .exp-del {
            cursor: pointer;
            color: #ff9800;
            font-weight: bold;
        }

        footer {
            margin-top: 40px;
            text-align: center;
            font-size: 14px;
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>Personal Expense Tracker</h1>
        <p>Total Expenses: <span id="total">0.00</span></p>
    </div>

    <ul class="expenses-container" id="expenses">
        <!-- Expense list will be built here -->
        <li class="form-group" data-category="groceries" data-date="2023-01-01">
            <input type="number" id="amount1" placeholder="Amount" maxlength="10"><br>
            <select id="category-filter" onchange="this.style.display='none;'"></select><br>
            <div class="note-input">Enter date (optional)</div>
            <button id="add-expense-btn">Add Expense</button>
        </li>
    </ul>

    <footer>
        <p>This tracker uses localStorage for persistence.</p>
    </footer>

    <script>
        // Persistence: Load expenses from localStorage on page load
        const loadExpenses = () => {
            let savedData;
            if (localStorage.getItem('expenses')) {
                savedData = JSON.parse(localStorage.getItem('expenses'));
                // Convert to array of objects for easier manipulation
                const entries = savedData.map(item => ({
                    amount: Number(item.amount),
                    category: item.category,
                    date: item.date
                }));
            } else {
                // Create new expenses and save them
                const entries = [
                    { amount: 0, category: 'groceries', date: new Date() },
                    { amount: 5, category: 'transport', date: new Date() }
                ];
                savedData = entries;
            }
        };

        // Update localStorage on page load
        const updateLocalStorage = () => {
            localStorage.setItem('expenses', JSON.stringify(savedData));
        };

        // Initialize app
        window.addEventListener('DOMContentLoaded', (event) => {
            // Load expenses from storage if available, else create new array and save to storage
            loadExpenses();

            // Populate initial data based on saved data or empty array
            const entries = loadedData ? loadedData : [];

            // Initialize form with all categories and default date
            document.getElementById('category-filter').valueOptions = ['all', 'groceries', 'transport', 'bills', 'fun'];

            // Setup event listeners for filters (only for category filter, date input is read-only)
            const categorySelect = document.getElementById('category-filter');
            categorySelect.addEventListener('change', function() {
                this.style.display = 'none';
                updateExpenseList(); // Re-render list with current category
            });

            // Event for adding expense
            document.getElementById('add-expense-btn').addEventListener('click', (event) => {
                event.preventDefault();
                const amountInput = document.getElementById('amount1');
                const dateInput = document.createElement('div');
                dateInput.className = 'date-picker';
                dateInput.innerHTML = '<span class="date-input">Date</span>';

                // Allow typing or clicking to set date
                dateInput.addEventListener('click', () => {
                    const value = dateInput.innerText;
                    if (value) {
                        dateInput.innerText = new Date().toISOString().slice(0, 10);
                    }
                });
                dateInput.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') {
                        setDateForEntry(dateInput, amountInput);
                    }
                });

                // Validate and add expense
                const category = document.getElementById('category-filter').value;
                const amount = parseFloat(amountInput.value);

                if (!isNaN(amount) && !isNaN(category)) { // basic validation
                    const newDate = new Date();
                    updateLocalStorage();

                    // Create new expense and add to entries array
                    const newEntry = {
                        amount: parseFloat(amount),
                        category,
                        date: newDate.toISOString().split('T')[0] // YYYY-MM-DD
                    };
                    entries.push(newEntry);
                }

                // Re-render expenses list with updated data (add expense to top or bottom)
                updateExpenseList();
            });

            // Format total sum for display
            function formatTotal() {
                return parseFloat((entries.reduce((a, b) => a + b, 0)).toFixed(2));
            }
        };

        // Set date for new expense entry
        function setDateForEntry(dateInputElement, amountInputElement) {
            const dateValue = dateInputElement.innerText;
            const amountValue = parseFloat(amountInputElement.value);

            if (!isNaN(amountValue)) {
                const newDate = new Date();
                newDate.setHours(Math.floor(dateValue.split('-').slice(1).length));
                newDate.setMinutes(Math.floor(newDate.getMinutes() + Number(dateValue.split('-')[0].split('/')[1]) * 60));

                // Update expense entry
                const expense = entries.find(e => e.date === newDate);
                if (expense) {
                    expense.amount = amountValue;
                }

                // Save to localStorage
                saveExpenses();
            }
        }

        // Render expenses list
        function updateExpenseList() {
            // Get current category from filter or default category
            const category = document.getElementById('category-filter').value || 'all';

            // Filter entries for this category (and date range)
            const filteredEntries = entries.filter(entry => entry.category === category);

            // Format total
            const total = parseFloat(filteredEntries.reduce((a, b) => a + b, 0).toFixed(2));
            document.getElementById('total').innerText = `$${formatTotal()}`;
        }

        // Save expenses to localStorage (if not already present)
        function saveExpenses() {
            updateLocalStorage();
        };
    </script>
</body>
</html>
